}

// MemoryWhyRequest represents the input to the memory.why tool.
type MemoryWhyRequest struct {
	EntryID string `json:"entryId"`
}

// UnmarshalJSON supports both camelCase ("entryId") and snake_case ("entry_id").
func (r *MemoryWhyRequest) UnmarshalJSON(data []byte) error {
	type Alias MemoryWhyRequest
	aux := struct {
		*Alias
		EntryIDAlt string `json:"entry_id"`
	}{
		Alias: (*Alias)(r),
	}
	if err := json.Unmarshal(data, &aux); err != nil {
		return err
	}
	if r.EntryID == "" && aux.EntryIDAlt != "" {
		r.EntryID = aux.EntryIDAlt
	}
	return nil
}

// MemoryWhyResponse represents the output of the memory.why tool.
type MemoryWhyResponse struct {
	Result string `json:"result"`
}

