// HandleMemoryBrief implements the memory.brief tool handler.
// Returns scope name, active entry count, and formatted entries ([<type>] <id>: <text>).
func (s *Server) HandleMemoryBrief(ctx context.Context, req MemoryBriefRequest) (MemoryBriefResponse, error) {
	scope := strings.TrimSpace(req.Scope)
	if scope == "" {
		return MemoryBriefResponse{}, errors.New("scope is required")
	}

	entries, err := s.idx.ListEntriesByScope(ctx, scope)
	if err != nil {
		return MemoryBriefResponse{}, fmt.Errorf("listing entries for scope %s: %w", scope, err)
	}

	resolvedScope := scope
	if len(entries) == 0 {
		alias, err := s.idx.ResolveAlias(ctx, scope)
		if err == nil && alias != "" && alias != scope {
			resolvedScope = alias
			entries, err = s.idx.ListEntriesByScope(ctx, resolvedScope)
			if err != nil {
				return MemoryBriefResponse{}, fmt.Errorf("listing entries for resolved scope %s: %w", resolvedScope, err)
			}
		}
	}

	var activeEntries []dossiers.Entry
	for _, e := range entries {
		if !e.Retired && e.RetiredReason == "" && e.SupersededBy == "" {
			activeEntries = append(activeEntries, e)
		}
	}

	for _, e := range activeEntries {
		s.recordPull(e.ID)
	}

	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Scope: %s\nEntry count: %d\n", resolvedScope, len(activeEntries)))
	for _, e := range activeEntries {
		text := e.Text
		if len(text) > 200 {
			text = text[:200]
		}
		sb.WriteString(fmt.Sprintf("[%s] %s: %s\n", e.Type, e.ID, text))
	}

	return MemoryBriefResponse{Result: sb.String()}, nil
}

// HandleMemoryWhy implements the memory.why tool handler.
// Returns entry type, text, anchors, evidence list, verification status, timestamps, and history.
func (s *Server) HandleMemoryWhy(ctx context.Context, req MemoryWhyRequest) (MemoryWhyResponse, error) {
	entryID := strings.TrimSpace(req.EntryID)
	if entryID == "" {
		return MemoryWhyResponse{}, errors.New("entryId is required")
	}

	entry, err := s.idx.GetEntry(ctx, entryID)
	if err != nil {
		return MemoryWhyResponse{}, fmt.Errorf("getting entry %s: %w", entryID, err)
	}

	s.recordPull(entry.ID)

	hist, err := s.idx.GetHistory(ctx, entryID)
	if err != nil {
		return MemoryWhyResponse{}, fmt.Errorf("getting history for %s: %w", entryID, err)
	}

	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Entry: %s\n", entry.ID))
	sb.WriteString(fmt.Sprintf("Type: %s\n", entry.Type))
	sb.WriteString(fmt.Sprintf("Text: %s\n", entry.Text))

	if len(entry.Anchors) > 0 {
		sb.WriteString(fmt.Sprintf("Anchors: %s\n", strings.Join(entry.Anchors, ", ")))
	} else {
		sb.WriteString("Anchors: none\n")
	}

	evList := append([]string(nil), entry.Evidence...)
	if len(evList) == 0 {
		for _, line := range strings.Split(entry.Text, "\n") {
			trimmed := strings.TrimSpace(line)
			if strings.HasPrefix(strings.ToLower(trimmed), "evidence:") {
				parts := strings.SplitN(trimmed, ":", 2)
				if len(parts) == 2 {
					for _, item := range strings.Split(parts[1], ",") {
						if t := strings.TrimSpace(item); t != "" {
							evList = append(evList, t)
						}
					}
				}
			}
		}
	}

	if len(evList) > 0 {
		sb.WriteString(fmt.Sprintf("Evidence: %s\n", strings.Join(evList, ", ")))
	} else {
		sb.WriteString("Evidence: none\n")
	}

	if entry.Verified != "" {
		sb.WriteString(fmt.Sprintf("Verification Status: %s\n", entry.Verified))
	} else {
		sb.WriteString("Verification Status: unverified\n")
	}

	if !entry.CreatedAt.IsZero() {
		sb.WriteString(fmt.Sprintf("Created At: %s\n", entry.CreatedAt.UTC().Format(time.RFC3339)))
	}
	if !entry.UpdatedAt.IsZero() {
		sb.WriteString(fmt.Sprintf("Updated At: %s\n", entry.UpdatedAt.UTC().Format(time.RFC3339)))
	}

	if len(hist) > 0 {
		sb.WriteString("History:\n")
		for _, h := range hist {
			sb.WriteString(fmt.Sprintf("- [%s] %s: %s (superseded by: %s, retired reason: %s)\n",
				h.Type, h.ID, h.Text, h.SupersededBy, h.RetiredReason))
		}
	} else if entry.RetiredReason != "" || entry.SupersededBy != "" {
		sb.WriteString("History:\n")
		sb.WriteString(fmt.Sprintf("- Retired Reason: %s, Superseded By: %s\n", entry.RetiredReason, entry.SupersededBy))
	} else {
		sb.WriteString("History: none\n")
	}

	return MemoryWhyResponse{Result: sb.String()}, nil
}

// HandleMemoryHistory implements the memory.history tool handler.
// Returns retired and superseded entries for the given dossier scope.
func (s *Server) HandleMemoryHistory(ctx context.Context, req MemoryHistoryRequest) (MemoryHistoryResponse, error) {
	scope := strings.TrimSpace(req.Scope)
	if scope == "" {
		return MemoryHistoryResponse{}, errors.New("scope is required")
	}

	resolvedScope := scope
	alias, err := s.idx.ResolveAlias(ctx, scope)
	if err == nil && alias != "" {
		resolvedScope = alias
	}

	entries, err := s.idx.ListEntriesByScope(ctx, resolvedScope)
	if err != nil {
		return MemoryHistoryResponse{}, fmt.Errorf("listing entries for scope %s: %w", resolvedScope, err)
	}

	var retiredEntries []dossiers.Entry
	seen := make(map[string]bool)

	for _, e := range entries {
		if e.Retired || e.RetiredReason != "" || e.SupersededBy != "" {
			if !seen[e.ID] {
				seen[e.ID] = true
				retiredEntries = append(retiredEntries, e)
			}
		}
		histList, err := s.idx.GetHistory(ctx, e.ID)
		if err == nil {
			for _, h := range histList {
				key := fmt.Sprintf("%s:%s", h.ID, h.RetiredReason)
				if !seen[key] {
					seen[key] = true
					retiredEntries = append(retiredEntries, h)
				}
			}
		}
	}

	_ = s.idx.WriteTx(ctx, func(tx *sql.Tx) error {
		rows, err := tx.QueryContext(ctx, `
			SELECT entry_id, type, dossier_scope, text, reason, superseded_by, retired_at
			FROM entry_history
			WHERE dossier_scope = ?
			ORDER BY retired_at DESC
		`, resolvedScope)
		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			var eID, typeStr, dScope, text, reason, supersededBy, retiredAt sql.NullString
			if err := rows.Scan(&eID, &typeStr, &dScope, &text, &reason, &supersededBy, &retiredAt); err != nil {
				return err
			}
			key := fmt.Sprintf("%s:%s", eID.String, reason.String)
			if !seen[key] {
				seen[key] = true
				retiredEntries = append(retiredEntries, dossiers.Entry{
					ID:            eID.String,
					Type:          dossiers.EntryType(typeStr.String),
					DossierScope:  dScope.String,
					Text:          text.String,
					Retired:       true,
					RetiredReason: reason.String,
					SupersededBy:  supersededBy.String,
				})
			}
		}
		return rows.Err()
	})

	for _, e := range retiredEntries {
		s.recordPull(e.ID)
	}

	if len(retiredEntries) == 0 {
		return MemoryHistoryResponse{Result: fmt.Sprintf("Scope: %s (0 retired/superseded entries)", resolvedScope)}, nil
	}

	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Scope: %s (%d retired/superseded entries)\n", resolvedScope, len(retiredEntries)))
	for _, e := range retiredEntries {
		reason := e.RetiredReason
		if reason == "" && e.SupersededBy != "" {
			reason = fmt.Sprintf("superseded by %s", e.SupersededBy)
		} else if e.SupersededBy != "" {
			reason = fmt.Sprintf("%s (superseded by %s)", reason, e.SupersededBy)
		}
		if reason == "" {
			reason = "retired"
		}
		sb.WriteString(fmt.Sprintf("[%s] %s: %s (reason: %s)\n", e.Type, e.ID, e.Text, reason))
	}

	return MemoryHistoryResponse{Result: sb.String()}, nil
}

// HandleMemorySearch implements the memory.search tool handler.
// Performs FTS5 BM25 search over entries and returns top 10 ranked results with 100-char snippets.
func (s *Server) HandleMemorySearch(ctx context.Context, req MemorySearchRequest) (MemorySearchResponse, error) {
	query := strings.TrimSpace(req.Query)
	if query == "" {
		return MemorySearchResponse{Result: "No results found."}, nil
	}

	results, err := s.idx.SearchEntries(ctx, query)
	if err != nil {
		return MemorySearchResponse{}, fmt.Errorf("searching entries: %w", err)
	}

	if len(results) == 0 {
		return MemorySearchResponse{Result: "No results found."}, nil
	}

	if len(results) > 10 {
		results = results[:10]
	}

	for _, e := range results {
		s.recordPull(e.ID)
	}

	var sb strings.Builder
	for i, e := range results {
		snippet := e.Text
		if len(snippet) > 100 {
			snippet = snippet[:100]
		}
		sb.WriteString(fmt.Sprintf("%d. [%s] %s (scope: %s): %s\n", i+1, e.Type, e.ID, e.DossierScope, snippet))
	}

	return MemorySearchResponse{Result: sb.String()}, nil
}

// HandleMemoryNote implements the memory.note tool handler.
// Captures a memory note by appending an OpAdd operation to the ops log.
func (s *Server) HandleMemoryNote(ctx context.Context, req MemoryNoteRequest) (MemoryNoteResponse, error) {
	scope := strings.TrimSpace(req.Scope)
	if scope == "" {
		return MemoryNoteResponse{}, errors.New("scope is required")
	}

	text := strings.TrimSpace(req.Text)
	if text == "" {
		return MemoryNoteResponse{}, errors.New("text is required")
	}

	entryTypeStr := strings.TrimSpace(req.Type)
	if entryTypeStr == "" {
		entryTypeStr = string(dossiers.EntryTypeDecision)
	}

	entryType := dossiers.EntryType(entryTypeStr)
	switch entryType {
	case dossiers.EntryTypeInvariant,
		dossiers.EntryTypeRuledOut,
		dossiers.EntryTypeFailureSignature,
		dossiers.EntryTypeGotcha,
		dossiers.EntryTypeDecision,
		dossiers.EntryTypeProcedure,
		dossiers.EntryTypeInterface,
		dossiers.EntryTypeOpenIssue:
		// valid entry type
	default:
		return MemoryNoteResponse{}, fmt.Errorf("invalid entry type %q", entryTypeStr)
	}

	prefix := dossiers.EntryTypePrefixes[entryType]
	if prefix == "" {
		prefix = "dec-"
	}

	entryID := ops.NewEntryID(prefix)
	now := time.Now().UTC()

	op := ops.Op{
		Type:         ops.OpAdd,
		EntryID:      entryID,
		DossierScope: scope,
		Timestamp:    now,
		Source:       "agent",
		Fields: map[string]any{
			"entry_type": string(entryType),
			"text":       text,
		},
	}

	batch := ops.NewBatch([]ops.Op{op})
	writer := s.opsWriter
	if writer == nil {
		writer = ops.NewWriter(".memory/ops")
	}

	if err := writer.Write(batch); err != nil {
		return MemoryNoteResponse{}, fmt.Errorf("writing op: %w", err)
	}

	return MemoryNoteResponse{
		Result: fmt.Sprintf("Note recorded: %s", entryID),
	}, nil
}

package mcpserver

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/delivery"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
)

// Server provides MCP tool handlers for memory queries and capture over the index and op log.
type Server struct {
	idx       *index.Index
	ledger    *delivery.Ledger
	opsWriter *ops.Writer
}

// ServerOption configures an MCP server instance.
type ServerOption func(*Server)

// WithLedger configures a delivery ledger for recording pull exposures.
func WithLedger(l *delivery.Ledger) ServerOption {
	return func(s *Server) {
		s.ledger = l
	}
}

// WithOpsWriter configures a specific ops writer for memory note writes.
func WithOpsWriter(w *ops.Writer) ServerOption {
	return func(s *Server) {
		s.opsWriter = w
	}
}

// WithOpsDir configures the directory used by the default ops writer.
func WithOpsDir(dir string) ServerOption {
	return func(s *Server) {
		s.opsWriter = ops.NewWriter(dir)
	}
}

// NewServer creates a new MCP server.
func NewServer(idx *index.Index, opts ...ServerOption) *Server {
	s := &Server{idx: idx}
	for _, opt := range opts {
		opt(s)
	}
	return s
}

// SetLedger configures or updates the delivery ledger.
func (s *Server) SetLedger(l *delivery.Ledger) {
	s.ledger = l
}

// SetOpsWriter configures or updates the ops writer.
func (s *Server) SetOpsWriter(w *ops.Writer) {
	s.opsWriter = w
}

func (s *Server) recordPull(entryID string) {
	if s.ledger != nil && entryID != "" {
		s.ledger.RecordPull(entryID)
	}
}

// Tool name constants exposed by the MCP server.
const (
	ToolMemoryBrief   = "memory.brief"
	ToolMemoryWhy     = "memory.why"
	ToolMemoryHistory = "memory.history"
	ToolMemorySearch  = "memory.search"
	ToolMemoryNote    = "memory.note"
	ToolMemoryAsk     = "memory.ask" // Deprecated: use ToolMemorySearch
)

// ToolDef contains descriptive metadata for a registered MCP tool.
type ToolDef struct {
	Name        string `json:"name"`
	Description string `json:"description"`
}

// RegisteredTools returns descriptions of all available MCP tools.
func (s *Server) RegisteredTools() []ToolDef {
	return []ToolDef{
		{Name: ToolMemoryBrief, Description: "Dossier summary and invariants for a scope"},
		{Name: ToolMemoryWhy, Description: "Rationale, evidence, and history for an entry"},
		{Name: ToolMemoryHistory, Description: "Retired and superseded entries for a scope"},
		{Name: ToolMemorySearch, Description: "Full-text BM25 search over entries"},
		{Name: ToolMemoryNote, Description: "Agent-prompted memory capture (write to inbox)"},
	}
}

// CallTool dispatches a tool execution by name using raw JSON arguments.
func (s *Server) CallTool(ctx context.Context, name string, argsJSON []byte) (any, error) {
	switch name {
	case ToolMemoryBrief:
		var req MemoryBriefRequest
		if len(argsJSON) > 0 {
			if err := json.Unmarshal(argsJSON, &req); err != nil {
				return nil, fmt.Errorf("unmarshaling %s request: %w", name, err)
			}
		}
		return s.HandleMemoryBrief(ctx, req)
	case ToolMemoryWhy:
		var req MemoryWhyRequest
		if len(argsJSON) > 0 {
			if err := json.Unmarshal(argsJSON, &req); err != nil {
				return nil, fmt.Errorf("unmarshaling %s request: %w", name, err)
			}
		}
		return s.HandleMemoryWhy(ctx, req)
	case ToolMemoryHistory:
		var req MemoryHistoryRequest
		if len(argsJSON) > 0 {
			if err := json.Unmarshal(argsJSON, &req); err != nil {
				return nil, fmt.Errorf("unmarshaling %s request: %w", name, err)
			}
		}
		return s.HandleMemoryHistory(ctx, req)
	case ToolMemorySearch:
		var req MemorySearchRequest
		if len(argsJSON) > 0 {
			if err := json.Unmarshal(argsJSON, &req); err != nil {
				return nil, fmt.Errorf("unmarshaling %s request: %w", name, err)
			}
		}
		return s.HandleMemorySearch(ctx, req)
	case ToolMemoryNote:
		var req MemoryNoteRequest
		if len(argsJSON) > 0 {
			if err := json.Unmarshal(argsJSON, &req); err != nil {
				return nil, fmt.Errorf("unmarshaling %s request: %w", name, err)
			}
		}
		return s.HandleMemoryNote(ctx, req)
	case ToolMemoryAsk:
		var req MemoryAskRequest
		if len(argsJSON) > 0 {
			if err := json.Unmarshal(argsJSON, &req); err != nil {
				return nil, fmt.Errorf("unmarshaling %s request: %w", name, err)
			}
		}
		return s.HandleMemoryAsk(ctx, req)
	default:
		return nil, fmt.Errorf("unknown tool: %s", name)
	}
}

// MemoryAskRequest represents the input to the memory.ask tool.
// Deprecated: use MemorySearchRequest instead.
type MemoryAskRequest struct {
	Query string `json:"query"`
}

// MemoryAskResponse represents the output of the memory.ask tool.
// Deprecated: use MemorySearchResponse instead.
type MemoryAskResponse struct {
	Result string `json:"result"`
}

// HandleMemoryAsk implements the memory.ask tool handler.
// Deprecated: use HandleMemorySearch instead.
func (s *Server) HandleMemoryAsk(ctx context.Context, req MemoryAskRequest) (MemoryAskResponse, error) {
	results, err := s.idx.SearchEpisodes(ctx, req.Query)
	if err != nil {
		return MemoryAskResponse{}, fmt.Errorf("searching episodes: %w", err)
	}

	if len(results) == 0 {
		return MemoryAskResponse{Result: "No results found."}, nil
	}

	var output string
	for i, res := range results {
		output += fmt.Sprintf("Result %d [unverified (episode search)]:\n", i+1)
		output += fmt.Sprintf("Episode ID: %s\n", res.EpisodeID)
		if res.Snippet != "" {
			output += fmt.Sprintf("Match: %s\n", res.Snippet)
		} else {
			output += fmt.Sprintf("Match: %s\n", res.Content)
		}
		output += "\n"
	}

	return MemoryAskResponse{Result: output}, nil
}

package mcpserver_test

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/delivery"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/ops"
	"github.com/cblabs-org/repo-memory-plugin/internal/mcpserver"
)

func setupTestServer(t *testing.T) (*index.Index, *mcpserver.Server, *delivery.Ledger, string) {
	t.Helper()
	idx, err := index.NewIndex(":memory:")
	if err != nil {
		t.Fatalf("failed to create in-memory index: %v", err)
	}

	opsDir := t.TempDir()
	opsWriter := ops.NewWriter(opsDir)
	ledger := delivery.NewLedger("conv-test-1")

	srv := mcpserver.NewServer(idx,
		mcpserver.WithLedger(ledger),
		mcpserver.WithOpsWriter(opsWriter),
	)

	return idx, srv, ledger, opsDir
}

// 1. memory.brief: Set up index with entries in a known scope -> verify formatted output
func TestHandleMemoryBrief_BasicAndFormatting(t *testing.T) {
	idx, srv, ledger, _ := setupTestServer(t)
	defer idx.Close()

	ctx := context.Background()

	// Insert entries into scope "core/storage"
	entry1 := dossiers.Entry{
		ID:           "inv-001",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "core/storage",
		Text:         "WAL mode must always be enabled.",
		CreatedAt:    time.Now().UTC(),
		UpdatedAt:    time.Now().UTC(),
	}
	longText := strings.Repeat("A very detailed explanation of why storage requires durability guarantees. ", 5)
	entry2 := dossiers.Entry{
		ID:           "dec-002",
		Type:         dossiers.EntryTypeDecision,
		DossierScope: "core/storage",
		Text:         longText,
		CreatedAt:    time.Now().UTC(),
		UpdatedAt:    time.Now().UTC(),
	}
	// Retired entry should be filtered out
	retiredEntry := dossiers.Entry{
		ID:            "rul-003",
		Type:          dossiers.EntryTypeRuledOut,
		DossierScope:  "core/storage",
		Text:          "Do not use in-memory mode in production.",
		Retired:       true,
		RetiredReason: "obsolete",
		CreatedAt:    time.Now().UTC(),
		UpdatedAt:    time.Now().UTC(),
	}

	if err := idx.UpsertEntry(ctx, entry1); err != nil {
		t.Fatalf("upsert entry1: %v", err)
	}
	if err := idx.UpsertEntry(ctx, entry2); err != nil {
		t.Fatalf("upsert entry2: %v", err)
	}
	if err := idx.UpsertEntry(ctx, retiredEntry); err != nil {
		t.Fatalf("upsert retiredEntry: %v", err)
	}

	resp, err := srv.HandleMemoryBrief(ctx, mcpserver.MemoryBriefRequest{Scope: "core/storage"})
	if err != nil {
		t.Fatalf("HandleMemoryBrief failed: %v", err)
	}

	// Verify formatted output
	if !strings.Contains(resp.Result, "Scope: core/storage") {
		t.Errorf("expected scope header, got: %s", resp.Result)
	}
	if !strings.Contains(resp.Result, "Entry count: 2") {
		t.Errorf("expected 2 active entries, got: %s", resp.Result)
	}
	if !strings.Contains(resp.Result, "[invariant] inv-001: WAL mode must always be enabled.") {
		t.Errorf("expected formatted entry1, got: %s", resp.Result)
	}
	if !strings.Contains(resp.Result, "[decision] dec-002:") {
		t.Errorf("expected formatted entry2, got: %s", resp.Result)
	}
	if strings.Contains(resp.Result, "rul-003") {
		t.Errorf("retired entry should not appear in brief: %s", resp.Result)
	}

	// Verify truncation to 200 chars for long entry
	lines := strings.Split(resp.Result, "\n")
	for _, line := range lines {
		if strings.HasPrefix(line, "[decision] dec-002:") {
			textPart := strings.TrimPrefix(line, "[decision] dec-002: ")
			if len(textPart) > 200 {
				t.Errorf("entry text exceeds 200 chars: %d chars", len(textPart))
			}
		}
	}

	// Verify pull exposure recorded in ledger
	exposures := ledger.GetExposureList()
	foundInv1 := false
	foundDec2 := false
	for _, exp := range exposures {
		if exp.Channel == "pull" && exp.EntryID == "inv-001" {
			foundInv1 = true
		}
		if exp.Channel == "pull" && exp.EntryID == "dec-002" {
			foundDec2 = true
		}
	}
	if !foundInv1 || !foundDec2 {
		t.Errorf("expected pull exposures for inv-001 and dec-002, got: %+v", exposures)
	}
}

// 2. Alias resolution: Set up alias -> verify brief resolves correctly
