// 4. memory.search: Set up entries with searchable text -> verify FTS results
func TestHandleMemorySearch_FTSResults(t *testing.T) {
	idx, srv, ledger, _ := setupTestServer(t)
	defer idx.Close()

	ctx := context.Background()

	e1 := dossiers.Entry{
		ID:           "dec-301",
		Type:         dossiers.EntryTypeDecision,
		DossierScope: "auth/session",
		Text:         "JWT tokens must expire after fifteen minutes of inactivity.",
		CreatedAt:    time.Now().UTC(),
		UpdatedAt:    time.Now().UTC(),
	}
	e2 := dossiers.Entry{
		ID:           "inv-302",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "auth/session",
		Text:         "Session tokens are revoked on password change.",
		CreatedAt:    time.Now().UTC(),
		UpdatedAt:    time.Now().UTC(),
	}
	e3 := dossiers.Entry{
		ID:           "got-303",
		Type:         dossiers.EntryTypeGotcha,
		DossierScope: "database/migration",
		Text:         "Running sqlite vacuum during active transactions causes lock timeouts.",
		CreatedAt:    time.Now().UTC(),
		UpdatedAt:    time.Now().UTC(),
	}

	for _, e := range []dossiers.Entry{e1, e2, e3} {
		if err := idx.UpsertEntry(ctx, e); err != nil {
			t.Fatalf("upsert %s: %v", e.ID, err)
		}
	}

	// Search for "tokens"
	resp, err := srv.HandleMemorySearch(ctx, mcpserver.MemorySearchRequest{Query: "tokens"})
	if err != nil {
		t.Fatalf("HandleMemorySearch failed: %v", err)
	}

	if !strings.Contains(resp.Result, "dec-301") {
		t.Errorf("expected dec-301 in search results, got: %s", resp.Result)
	}
	if !strings.Contains(resp.Result, "inv-302") {
		t.Errorf("expected inv-302 in search results, got: %s", resp.Result)
	}
	if strings.Contains(resp.Result, "got-303") {
		t.Errorf("got-303 should not match 'tokens', got: %s", resp.Result)
	}

	// Verify ranking format: "1. [decision] dec-301 (scope: auth/session): ..."
	if !strings.Contains(resp.Result, "1. [") {
		t.Errorf("expected numbered ranked list format, got: %s", resp.Result)
	}

	// Verify pull exposure recorded in ledger
	exposures := ledger.GetExposureList()
	found1 := false
	found2 := false
	for _, exp := range exposures {
		if exp.Channel == "pull" && exp.EntryID == "dec-301" {
			found1 = true
		}
		if exp.Channel == "pull" && exp.EntryID == "inv-302" {
			found2 = true
		}
	}
	if !found1 || !found2 {
		t.Errorf("expected exposures for search matches in ledger")
	}

	// Test empty query returns no results found
	emptyResp, err := srv.HandleMemorySearch(ctx, mcpserver.MemorySearchRequest{Query: ""})
	if err != nil {
		t.Fatalf("empty search failed: %v", err)
	}
	if emptyResp.Result != "No results found." {
		t.Errorf("expected 'No results found.', got: %s", emptyResp.Result)
	}
}

