// 6. memory.note: Verify note creates an op (or returns the entry ID)
func TestHandleMemoryNote_CreatesOp(t *testing.T) {
	idx, srv, _, opsDir := setupTestServer(t)
	defer idx.Close()

	ctx := context.Background()

	req := mcpserver.MemoryNoteRequest{
		Scope: "core/api",
		Text:  "We agreed to standardize on REST API error format v2.",
		Type:  "decision",
	}

	resp, err := srv.HandleMemoryNote(ctx, req)
	if err != nil {
		t.Fatalf("HandleMemoryNote failed: %v", err)
	}

	if !strings.HasPrefix(resp.Result, "Note recorded: dec-") {
		t.Errorf("expected response 'Note recorded: dec-...', got: %s", resp.Result)
	}

	entryID := strings.TrimPrefix(resp.Result, "Note recorded: ")

	// Verify batch file was written to ops directory
	reader := ops.NewReader(opsDir)
	foundOp := false
	for batch, err := range reader.Iterate(ctx) {
		if err != nil {
			t.Fatalf("reading ops batch: %v", err)
		}
		for _, op := range batch.Ops {
			if op.EntryID == entryID {
				foundOp = true
				if op.Type != ops.OpAdd {
					t.Errorf("expected op type add, got: %s", op.Type)
				}
				if op.DossierScope != "core/api" {
					t.Errorf("expected scope core/api, got: %s", op.DossierScope)
				}
				if op.Source != "agent" {
					t.Errorf("expected source agent, got: %s", op.Source)
				}
				if op.Fields["text"] != req.Text {
					t.Errorf("expected text %q, got %v", req.Text, op.Fields["text"])
				}
				if op.Fields["entry_type"] != "decision" {
					t.Errorf("expected entry_type decision, got %v", op.Fields["entry_type"])
				}
			}
		}
	}
	if !foundOp {
		t.Errorf("expected op %s to be written in op log", entryID)
	}
}

// Test default type and validation in memory.note
func TestHandleMemoryNote_DefaultTypeAndValidation(t *testing.T) {
	idx, srv, _, _ := setupTestServer(t)
	defer idx.Close()

	ctx := context.Background()

	// Default type when Type is omitted: should default to decision ("dec-")
	resp, err := srv.HandleMemoryNote(ctx, mcpserver.MemoryNoteRequest{
		Scope: "core/misc",
		Text:  "Architecture decision note.",
	})
	if err != nil {
		t.Fatalf("HandleMemoryNote with default type failed: %v", err)
	}
	if !strings.HasPrefix(resp.Result, "Note recorded: dec-") {
		t.Errorf("expected default dec- prefix, got: %s", resp.Result)
	}

	// Validation errors
	_, err = srv.HandleMemoryNote(ctx, mcpserver.MemoryNoteRequest{
		Scope: "",
		Text:  "Note text",
	})
	if err == nil || !strings.Contains(err.Error(), "scope is required") {
		t.Errorf("expected scope is required error, got: %v", err)
	}

	_, err = srv.HandleMemoryNote(ctx, mcpserver.MemoryNoteRequest{
		Scope: "core/misc",
		Text:  "",
	})
	if err == nil || !strings.Contains(err.Error(), "text is required") {
		t.Errorf("expected text is required error, got: %v", err)
	}

	_, err = srv.HandleMemoryNote(ctx, mcpserver.MemoryNoteRequest{
		Scope: "core/misc",
		Text:  "Note text",
		Type:  "invalid-type",
	})
	if err == nil || !strings.Contains(err.Error(), "invalid entry type") {
		t.Errorf("expected invalid entry type error, got: %v", err)
	}
}

// Test CallTool dispatcher and registered tools
func TestServer_CallToolAndRegisteredTools(t *testing.T) {
	idx, srv, _, _ := setupTestServer(t)
	defer idx.Close()

	ctx := context.Background()

	// Verify RegisteredTools
	tools := srv.RegisteredTools()
	expected := []string{
		"memory.brief",
		"memory.why",
		"memory.history",
		"memory.search",
		"memory.note",
	}
	for _, exp := range expected {
		found := false
		for _, tool := range tools {
			if tool.Name == exp {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("expected tool %s in RegisteredTools", exp)
		}
	}

	// Test CallTool for memory.note
	args, _ := json.Marshal(mcpserver.MemoryNoteRequest{
		Scope: "core/testing",
		Text:  "Tool dispatcher test note.",
		Type:  "procedure",
	})
	res, err := srv.CallTool(ctx, "memory.note", args)
	if err != nil {
		t.Fatalf("CallTool memory.note failed: %v", err)
	}
	noteResp, ok := res.(mcpserver.MemoryNoteResponse)
	if !ok || !strings.HasPrefix(noteResp.Result, "Note recorded: proc-") {
		t.Errorf("unexpected CallTool response: %v", res)
	}

	// Test CallTool for unknown tool
	_, err = srv.CallTool(ctx, "memory.unknown", nil)
	if err == nil || !strings.Contains(err.Error(), "unknown tool") {
		t.Errorf("expected unknown tool error, got: %v", err)
	}
}

// Test writing note with default ops dir if opsWriter is nil
func TestHandleMemoryNote_DefaultOpsDir(t *testing.T) {
	idx, err := index.NewIndex(":memory:")
	if err != nil {
		t.Fatalf("NewIndex: %v", err)
	}
	defer idx.Close()

	tempDir := t.TempDir()
	// Change current working directory or use WithOpsDir
	srv := mcpserver.NewServer(idx, mcpserver.WithOpsDir(tempDir))

	resp, err := srv.HandleMemoryNote(context.Background(), mcpserver.MemoryNoteRequest{
		Scope: "core/default-ops",
		Text:  "Test note using default ops dir option.",
	})
	if err != nil {
		t.Fatalf("HandleMemoryNote failed: %v", err)
	}
	if !strings.HasPrefix(resp.Result, "Note recorded: dec-") {
		t.Errorf("unexpected response: %s", resp.Result)
	}

	// Check file was created in tempDir
	matches, err := filepath.Glob(filepath.Join(tempDir, "*", "*.json"))
	if err != nil || len(matches) == 0 {
		t.Errorf("expected batch json file in %s, got %v", tempDir, matches)
	}
	for _, m := range matches {
		data, _ := os.ReadFile(m)
		if !strings.Contains(string(data), "Test note using default ops dir option.") {
			t.Errorf("batch file did not contain note text: %s", string(data))
		}
	}
}

